# Reviewed under AGENTS.md
from __future__ import annotations

from collections import OrderedDict
from typing import Generic, TypeVar

KeyT = TypeVar('KeyT')
ValueT = TypeVar('ValueT')


class LRUCache(Generic[KeyT, ValueT]):
    """A fixed-capacity least-recently-used cache.

    Both ``get`` and ``put`` count as a use: the touched key becomes the most recently used,
    and an insert that would exceed ``capacity`` evicts the least recently used key first.
    """

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError(f'capacity must be at least 1, got {capacity}')
        self._capacity = capacity
        # Ordered from least recently used (front) to most recently used (back).
        self._entries: OrderedDict[KeyT, ValueT] = OrderedDict()

    @property
    def capacity(self) -> int:
        return self._capacity

    def get(self, key: KeyT) -> ValueT | None:
        """Return the value for ``key``, or ``None`` if absent, marking the key as recently used."""
        if key not in self._entries:
            return None
        self._entries.move_to_end(key)
        return self._entries[key]

    def put(self, key: KeyT, value: ValueT) -> None:
        """Insert or update ``key``, marking it as recently used and evicting if over capacity."""
        if key in self._entries:
            self._entries.move_to_end(key)
        else:
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        self._entries[key] = value

    def __len__(self) -> int:
        return len(self._entries)

    def __contains__(self, key: object) -> bool:
        return key in self._entries

    def __repr__(self) -> str:
        return f'{type(self).__name__}(capacity={self._capacity}, entries={dict(self._entries)!r})'
